SELECT CASE WHEN w.entry_quality_score < 55 THEN 'a_50-54_LATE' WHEN w.entry_quality_score < 70 THEN 'b_55-69' WHEN w.entry_quality_score < 85 THEN 'c_70-84' ELSE 'd_85+' END AS eq_bucket, w.entry_stage, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, SUM(p.status = 'STOPPED') AS stopped, ROUND(SUM(p.realized_pnl), 6) AS gross_pnl FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position w ON w.entry_signal_id = p.signal_id AND w.symbol = p.symbol WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY eq_bucket, w.entry_stage ORDER BY eq_bucket, w.entry_stage LIMIT 60